<template><main class="public-board"><header><span class="brand">◈ 模型评测榜单</span><el-tag type="success" effect="plain" v-if="data">正式发布 · {{ date(data.created_at) }}</el-tag></header><div v-if="error" class="unavailable"><h1>此榜单当前不可查看</h1><p>{{ error }}</p></div><template v-else-if="data"><h1>{{ data.title }}</h1><p class="intro">同一评测协议下的正式发布结果。分数、权重和版本在发布时冻结。标有“演示配置”的名称代表同一底层模型的不同接入配置，小样本结果不代表通用能力认证。</p><div class="compare-switches"><el-checkbox-group v-model="selected" :max="5"><el-checkbox v-for="r in data.items" :key="r.key" :value="r.key">{{ r.model_name }}</el-checkbox></el-checkbox-group></div><div class="public-chart"><div class="legend"><span v-for="(r,i) in chosen" :key="r.key"><i :style="{background:colors[i]}" />{{ r.model_name }}</span></div><LeaderboardChart v-if="radar" :option="radar" height="410px" label="公开榜单能力雷达图" /><p v-else>当前选项不足三个共同维度，可查看下方分数表。</p></div><el-table :data="data.items" stripe><el-table-column label="排名" prop="rank" width="80" /><el-table-column label="模型" prop="model_name" min-width="230" fixed /><el-table-column label="版本" prop="version" width="100" /><el-table-column label="得分" width="110"><template #default="{row}">{{ row.ranking_score==null?'—':number(row.ranking_score*(data.scale&&data.board!=='value'?100:1),2) }}</template></el-table-column><el-table-column v-for="d in data.dimensions" :key="d" :label="d" width="130"><template #default="{row}">{{ row.dimensions[d]?.score==null?'—':number(row.dimensions[d].score*(data.scale?100:1),1) }}</template></el-table-column><el-table-column label="实测样本" prop="sample_count" width="100" /></el-table><p class="rules">{{ data.rules }}</p><p class="rules">本页面只提供已发布汇总结果，不包含原始题目、任务内容和接入凭证。每30秒核实发布状态；撤回后停止展示。</p></template><el-skeleton v-else :rows="8" animated /></main></template>
<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRoute } from 'vue-router'
import { leaderboardApi } from '@/api'
import LeaderboardChart from '@/components/LeaderboardChart.vue'
import { colors, number, radarOption } from '@/utils/leaderboardChartsV2'
const route=useRoute(),data=ref(null),error=ref(''),selected=ref([])
const chosen=computed(()=>selected.value.map(k=>data.value?.items.find(r=>r.key===k)).filter(Boolean))
const radar=computed(()=>radarOption(chosen.value,data.value?.dimensions || [],data.value?.scale))
const date=v=>new Date(`${v}Z`).toLocaleDateString('zh-CN')
let timer
async function load(){try{const result=await leaderboardApi.publicSnapshot(route.params.token);const first=!data.value;data.value=result;error.value='';if(first)selected.value=result.items.slice(0,2).map(r=>r.key)}catch(e){error.value=e.response?.data?.detail || '暂时无法核实发布状态，请稍后重试';data.value=null}}
onMounted(()=>{load();timer=setInterval(load,30000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<style scoped>.public-board{max-width:1220px;margin:auto;padding:30px 30px 60px;color:#253858}.public-board header{display:flex;align-items:center;justify-content:space-between;padding-bottom:28px;border-bottom:1px solid #e7edf6}.brand{font-size:17px;color:#2563eb;font-weight:650}.public-board h1{font-size:28px;margin:30px 0 12px}.intro,.rules{font-size:12px;color:#8594a9;line-height:1.9}.compare-switches{margin:24px 0 10px}.public-chart{border:1px solid #e2e9f4;border-radius:12px;margin:20px 0 28px;padding:20px}.legend{display:flex;justify-content:center;gap:25px;font-size:12px;color:#5d718d}.legend i{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:8px}.unavailable{padding:100px 20px;text-align:center}.rules{margin-top:22px}@media(max-width:700px){.public-board{padding:20px 14px}.public-board h1{font-size:22px}.legend{flex-wrap:wrap;gap:12px}}</style>
